import pytest
from src.auth import bearer_header

def test_bearer_header_strips_whitespace():
    token = '  abc123  '
    expected = {'Authorization': 'Bearer abc123'}
    assert bearer_header(token) == expected

def test_bearer_header_preserves_internal_whitespace():
    token = 'ab cd ef'
    expected = {'Authorization': 'Bearer ab cd ef'}
    assert bearer_header(token) == expected

def test_bearer_header_handles_newline_and_tab():
    token = '\\n\\t xyz789 \\n\\t'
    expected = {'Authorization': 'Bearer xyz789'}
    assert bearer_header(token) == expected

