import pytest
from src.auth import bearer_header

def test_bearer_header_strips_whitespace():
    assert bearer_header("  abc123  ") == {"Authorization": "Bearer abc123"}
    assert bearer_header(chr(10)+chr(9)+"token"+chr(10)) == {"Authorization": "Bearer token"}
    # internal spaces preserved
    assert bearer_header("  tok en  ") == {"Authorization": "Bearer tok en"}
    # empty after strip
    assert bearer_header("   ") == {"Authorization": "Bearer "}
    # no whitespace unchanged
    assert bearer_header("token") == {"Authorization": "Bearer token"}
